svg.script:
(function(){
  var base='/es/referencia/#dimensions';
  var dimCards=Array.prototype.slice.call(document.querySelectorAll('.lift-card'));
  var triadCards=Array.prototype.slice.call(document.querySelectorAll('.triad-detail'));
  function hideAll(){dimCards.forEach(function(c){c.classList.remove('is-on');});triadCards.forEach(function(c){c.classList.remove('is-on');});}
  function showDim(g){hideAll();var k=g.getAttribute('data-stage');var c=document.querySelector('.lift-card[data-stage="'+k+'"]');if(c)c.classList.add('is-on');}
  function showTriad(g){hideAll();var k=g.getAttribute('data-triad');var c=document.querySelector('.triad-detail[data-triad="'+k+'"]');if(c)c.classList.add('is-on');}
  function go(t){if(!t)return;try{window.top.location.href=t;}catch(e){window.location.href=t;}}
  document.querySelectorAll('.arqx-stage').forEach(function(g){
    g.addEventListener('mouseenter',function(){showDim(g);});g.addEventListener('mouseleave',hideAll);
    g.addEventListener('focus',function(){showDim(g);});g.addEventListener('blur',hideAll);
    g.addEventListener('click',function(){go(base);});
    g.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();go(base);}});
  });
  document.querySelectorAll('.triad-node').forEach(function(g){
    g.addEventListener('mouseenter',function(){showTriad(g);});g.addEventListener('mouseleave',hideAll);
    g.addEventListener('focus',function(){showTriad(g);});g.addEventListener('blur',hideAll);
    g.addEventListener('click',function(){go(g.getAttribute('data-target'));});
    g.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();go(g.getAttribute('data-target'));}});
  });
})();
